import React from "react";

const Confirmation = () => {
  return (
    <div className="max-w-md mx-auto mt-10 bg-white p-8 rounded-lg shadow-md text-center">
      <h2 className="text-2xl font-bold mb-4 text-green-600">Your booking has been confirmed.</h2>
      <p className="text-yellow-600 bg-yellow-100 p-4 rounded-md">
        <strong>Warning:</strong> Late return may result in a penalty.
      </p>
    </div>
  );
};

export default Confirmation;
